  mCmd_p1_Reg := Bits(0)
  mAddr_p1_Reg := Bits(0)
  mData_p1_Reg := Bits(0)
  mDataByteEn_p1_Reg := Bits(0)
  mDataValid_p1_Reg := Bits(0)

